"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[839],{7666:(e,a,o)=>{o.d(a,{P:()=>i});let i={name:"Blend Hair Boutique",tagline:"Luxury Hair & Beauty With a Brazilian Touch",city:"Plantation, Florida",address:"10035 Cleary Blvd, Plantation, FL 33324",addressStreet:"10035 Cleary Blvd",addressCity:"Plantation",addressState:"FL",addressZip:"33324",phone:"(754) 206-3501",phoneHref:"tel:+17542063501",whatsappNumber:"19545446792",whatsapp:"https://wa.me/19545446792",email:"info@blendhairboutique.com",instagram:"https://www.instagram.com/blendhairboutique",facebook:"https://www.facebook.com/blendhairboutique",tiktok:"https://www.tiktok.com/@blendhairboutique",bookingUrl:"https://www.fresha.com/book-now/blend-hair-boutique-tsmvse5t/all-offer",giftCardUrl:"https://www.fresha.com/book-now/blend-hair-boutique-tsmvse5t/all-offer",mapsDirections:"https://maps.google.com/?q=10035+Cleary+Blvd,+Plantation,+FL+33324",mapsEmbedUrl:"https://maps.google.com/maps?q=10035%20Cleary%20Blvd%2C%20Plantation%2C%20FL%2033324&output=embed&z=16",hours:[{day:"Monday",time:"9:00 AM – 6:00 PM"},{day:"Tuesday",time:"9:00 AM – 6:00 PM"},{day:"Wednesday",time:"9:00 AM – 6:00 PM"},{day:"Thursday",time:"9:00 AM – 7:00 PM"},{day:"Friday",time:"9:00 AM – 7:00 PM"},{day:"Saturday",time:"9:00 AM – 7:00 PM"},{day:"Sunday",time:"Closed"}]}},7687:(e,a,o)=>{o.d(a,{o:()=>n,u:()=>r});var i=o(5155),s=o(2115);let t=(0,s.createContext)({lang:"en",setLang:()=>{}});function n(e){let{children:a}=e,[o,n]=(0,s.useState)("en");return(0,i.jsx)(t.Provider,{value:{lang:o,setLang:n},children:a})}function r(){return(0,s.useContext)(t)}},9853:(e,a,o)=>{o.d(a,{T:()=>s});let i=new Date().getFullYear(),s={en:{announcement:"✦ Now booking — book online for instant confirmation \xb7 (754) 206-3501",nav:{services:"Services",gallery:"Gallery",team:"Team",about:"About",location:"Contact",bookNow:"Book Now"},hero:{eyebrow:"Plantation, FL \xb7 Est. 2012",h1:["Beauty","as a","ritual."],sub:"A sanctuary of artistry and Brazilian warmth in the heart of South Florida. Every visit, a transformation.",cta1:"Reserve Your Visit",cta2:"Call the Boutique",badge:"4.9 \xb7 1218 Google Reviews",badgeSub:"Plantation's most loved salon"},trustBar:["K\xe9rastase Salon","Brazilian Specialists","5-Star Rated \xb7 1218 Reviews","Since 2012","Plantation, Florida"],services:{eyebrow:"The Craft",h2a:"Every service,",h2b:"curated.",body:"Precision color. Brazilian smoothing. Refined cuts. Each treatment begins with listening — and ends with transformation.",viewAll:"View All Services",bookNow:"Reserve →"},servicesData:[{category:"Hair Color",title:"Color & Balayage",benefit:"Dimension, depth, and luminosity designed for your lifestyle.",description:"From sun-kissed balayage to rich all-over color, our colorists craft custom formulas tailored to your hair texture, skin tone, and maintenance preferences.",detail:"Our color services begin with a thorough consultation to understand your vision and hair history. We use professional-grade color lines that protect hair integrity while delivering vibrant, lasting results.",priceNote:"Starting price available upon booking",badge:"Most Requested"},{category:"Cut & Style",title:"Haircuts & Styling",benefit:"A cut that works for your hair, your life, your confidence.",description:"Precision cuts, lived-in layers, and blowout styling that flatter your face shape and require minimal daily effort.",detail:"Every cut begins with a dry consultation, assessing your natural texture and growth patterns before a single snip. We finish with a style that shows you exactly how to recreate the look at home.",priceNote:"Starting price available upon booking",badge:null},{category:"Smoothing Treatments",title:"Brazilian Blowout & Keratin",benefit:"Frizz-free, smooth, and manageable hair for months.",description:"Our Brazilian-inspired smoothing treatments eliminate frizz, reduce styling time, and leave your hair brilliantly smooth, soft, and healthy-looking.",detail:"We offer a range of keratin and smoothing treatments calibrated to your hair type — from a gentle smoothing for sensitive hair to a full Brazilian blowout for dramatically frizzy or coarse textures. Results last 3–5 months.",priceNote:"Starting price available upon booking",badge:"Signature Service"},{category:"Nails",title:"Nail Services",benefit:"Beautiful, lasting nails to complete your look.",description:"Manicures, pedicures, gel, and nail art. Our nail technicians deliver polished, precise results whether you prefer timeless classics or statement designs.",detail:"From a clean, natural manicure to intricate nail art, we use professional products and sanitized tools for every client. Gel services include extended-wear topcoats for lasting shine.",priceNote:"Starting price available upon booking",badge:null},{category:"Skin & Spa",title:"Facials & Spa",benefit:"Radiant skin and a moment of pure restoration.",description:"Customized facials, hydrating treatments, and spa rituals designed to brighten, balance, and restore your skin's natural glow.",detail:"Our skin treatments are personalized to your skin type and concerns. Whether you're targeting dullness, dehydration, or simply need a moment of self-care, our estheticians create a tailored experience.",priceNote:"Starting price available upon booking",badge:null},{category:"Waxing & Brows",title:"Waxing & Brow Shaping",benefit:"Defined brows and smooth skin that frame your features.",description:"Full and partial body waxing, eyebrow shaping, and brow tinting performed with precision and care.",detail:"We use premium waxes suited to sensitive skin. All brow services are shaped to complement your natural face structure, not override it — the goal is always your best version, naturally.",priceNote:"Starting price available upon booking",badge:null},{category:"Extensions",title:"Hair Extensions",benefit:"Instant length, volume, and versatility.",description:"Premium hair extensions applied for a seamless, natural look that blends beautifully with your own hair.",detail:"Our extension specialists work with high-quality, ethically sourced hair. We recommend the best application method for your hair type and lifestyle — tape-in, sew-in, or clip-in.",priceNote:"Consultation required — pricing varies by length and method",badge:null},{category:"Bridal & Events",title:"Bridal & Event Beauty",benefit:"Unforgettable beauty for your most important moments.",description:"Bridal packages, event styling, and beauty preparation for the days that matter most — hair, nails, and skin, all in one boutique.",detail:"From your engagement to your wedding day, we offer coordinated beauty packages that include trials, day-of styling, and on-location services. We also cater to bridal parties with group packages.",priceNote:"Custom packages — book a bridal consultation",badge:"Book Early"}],faqData:[{q:"How do I book an appointment at Blend Hair Boutique?",a:"You can book directly online through our Fresha booking system — available 24/7. Select your service, preferred stylist, and time. For bridal packages or consultations, contact us by phone at (754) 206-3501 or WhatsApp at (954) 544-6792."},{q:"Where is Blend Hair Boutique located?",a:"Blend Hair Boutique is located at 10035 Cleary Blvd, Plantation, FL 33324, in Broward County, South Florida. We are conveniently accessible from Plantation, Davie, Weston, Fort Lauderdale, Sunrise, Cooper City, and Pembroke Pines."},{q:"What are your hours?",a:"We are open Monday through Wednesday 9 AM–6 PM, Thursday through Saturday 9 AM–7 PM, and closed on Sunday. Walk-ins are welcome, but appointments are recommended to secure your preferred time and stylist."},{q:"What should I expect at my first visit?",a:"Every new client begins with a thorough consultation. We ask about your hair history, current routine, lifestyle, and goals before recommending any service. This ensures we always deliver results tailored to you."},{q:"How long does a balayage appointment take?",a:"Balayage appointments typically range from 2.5 to 4 hours depending on your hair length, density, and the result you're aiming for. We'll give you a realistic time estimate during booking or consultation."},{q:"Do you specialize in balayage and blonding?",a:"Yes. Color and balayage is our most requested service. Our colorists specialize in custom balayage, highlights, blonding, and color correction — tailored to your hair texture, skin tone, and maintenance lifestyle."},{q:"Do you do Brazilian blowouts and keratin treatments?",a:"Yes. Brazilian blowout and keratin smoothing treatments are a signature service at Blend — especially popular given Florida's humidity. Results typically last 3–5 months."},{q:"Do you offer hair extensions?",a:"Yes. We offer premium hair extensions including tape-in, sew-in, and clip-in methods. A consultation is required to assess your hair type and determine the best application method."},{q:"Do you offer bridal hair packages?",a:"Yes. Blend offers full bridal beauty packages including hair, nails, and skin services. We provide bridal trials, day-of styling, and group packages for bridal parties throughout South Florida."},{q:"What languages does the Blend team speak?",a:"The Blend Hair Boutique team is multilingual — we serve clients in English, Portuguese, and Spanish."},{q:"Do you offer gift cards?",a:"Yes — we offer gift cards in any amount, perfect for the people in your life who deserve a little luxury. They can be purchased online or in the boutique."},{q:"What is your cancellation policy?",a:"We ask for at least 24 hours' notice for cancellations or rescheduling. Late cancellations or no-shows may be subject to a fee. We appreciate your understanding — it helps us serve all clients well."},{q:"Do you use K\xe9rastase or professional hair care products?",a:"We work with professional-grade color and care lines selected for performance and hair health. We're always happy to recommend home-care products that complement your in-salon treatment."}],experience:{eyebrow:"The Blend Experience",h2a:"More than a salon —",h2b:"a Brazilian ritual.",body:"Stepping into Blend is unlike any other salon visit. We greet you with espresso served in fine porcelain, sparkling water, and the warmth of Brazilian hospitality — because beauty is about how you feel from the moment you arrive.",highlights:["Welcome ritual: espresso & sparkling water on arrival","Brazilian-trained stylists with 10+ years of experience","Premium professional products from K\xe9rastase","Personalized consultation before every service","Bilingual service — English & Portuguese"],cta1:"Meet Our Stylists",cta2:"Our Story"},gallery:{eyebrow:"Transformations",h2a:"Work We're ",h2b:"Proud Of",categories:["All","Color","Blonde","Brunette","Smoothing","Nails","Bridal"],viewAll:"Full Gallery",placeholderNote:"Gallery images are placeholders — replace with your real salon photography.",labels:["Sun-Kissed Balayage","Smooth Blowout","Rich Brunette Color","Nail Art","Highlights & Dimension","Bridal Elegance","Lived-in Color","Blowout & Style","Keratin Treatment","Extensions & Volume","Glow Facial","Color Transformation"],shortDescs:["Hand-painted highlights for natural, sun-kissed warmth.","Frizz-free volume with a polished salon finish.","Deep, multi-dimensional brunette with warm undertones.","Artisan nail designs for every style and occasion.","Precise foil highlights for bright, layered dimension.","Flawless bridal styling tailored for your most important day.","Effortless color that looks intentionally grown out.","Voluminous, smooth blow-dry with expert shaping.","Brazilian keratin to eliminate frizz for up to 4 months.","Seamless extensions for instant length and fullness.","Radiance-boosting treatment for luminous, healthy skin.","Full color makeover to your perfect brunette tone."],descs:["Balayage is a freehand color-painting technique that creates soft, seamless highlights with no harsh lines. The result grows out beautifully, making it one of the lowest-maintenance color services available.","A professional blowout smooths the cuticle, eliminates frizz, and adds long-lasting body and shine. Using heat-protective products and expert tension-drying techniques, we create a finish that stays fresh for days.","Full brunette color services use professional-grade formulas to build rich, dimensional depth that catches light beautifully.","From clean minimalism to intricate hand-painted detail, our nail services include gel polish, nail art, and extensions.","Traditional foil highlighting creates precise, luminous dimension throughout the hair — giving you visible brightness and striking contrast.","Bridal services begin with a dedicated trial appointment to finalize your perfect look. On the day, we offer full styling for the bride and wedding party.","Lived-in color mimics the natural way hair fades — beautifully. A low-maintenance technique using shadow roots, diffused mid-lengths, and softly brightened ends.","Our signature Blend blowout combines heat-protective serums, tension-based drying, and round-brush shaping to deliver lasting body and a mirror-like finish.","A professional Brazilian keratin smoothing treatment infuses protein deep into the hair shaft, sealing the cuticle and dramatically eliminating frizz.","Our extension services add seamless, natural-looking length and density without damage to your existing hair.","A restorative facial treatment targeting hydration, texture, and overall radiance using clinical-grade serums.","A complete color transformation service — from in-depth consultation to final reveal."],statsLabels:["Google Reviews","Google Rating","Years of Artistry","Brazilian Craftsmanship"],baSection:{eyebrow:"The Blend Difference",h2a:"Before & ",h2b:"After",sub:"Drag the handle to reveal the transformation. Real results, real clients.",before:"Before",after:"After"},baPairs:["Brunette to Balayage","Frizz to Silk Finish","Everyday to Bridal"],editorial:{eyebrow:"Crafted by Blend Artists",h2a:"Every result is a ",h2b:"collaboration.",sub:"Each transformation begins with a conversation — understanding your hair, your life, and your vision.",cta:"Book Your Transformation"},testimonial:{eyebrow:"Client Story",quote:"I’ve been to many salons in South Florida and Blend is simply on another level. My balayage looked effortlessly natural and the color lasted beautifully. I finally found my salon.",author:"Mariana T.\xa0\xb7\xa0Balayage"}},reviews:{eyebrow:"Client Stories",h2a:"Words that ",h2b:"speak for themselves",body:"Real words from the people we have the privilege of serving.",googleRating:"Google Reviews"},reviewsData:[{quote:"I've been to many salons in South Florida and Blend is simply on another level. My balayage looked effortlessly natural and the color lasted beautifully. I finally found my salon.",author:"Mariana T.",service:"Balayage"},{quote:"The Brazilian blowout here is the best I've ever had. My hair has never been this smooth, even in Florida humidity. The whole experience felt like a luxury boutique.",author:"Sophia R.",service:"Brazilian Blowout"},{quote:"They really listen. I walked in nervous about a big change and walked out feeling like the best version of myself. The consultation alone was worth the visit.",author:"Jennifer L.",service:"Haircut & Style"}],cta:{eyebrow:"Your Moment Awaits",h2:"Every visit, a new beginning.",sub:"Step into Blend and experience beauty the way it was always meant to feel — personal, unhurried, and unforgettable.",book:"Reserve Your Visit",secondary:"Get in Touch"},contact:{eyebrow:"Find Us",h2a:"Come Visit ",h2b:"Blend",body:"In the heart of Plantation, Florida — easy to find, impossible to forget.",address:"Address",phone:"Phone",whatsapp:"WhatsApp",whatsappLink:"Send us a message",email:"Email",instagram:"Instagram",hours:"Hours"},footer:{tagline:"Luxury hair color, smoothing treatments, nails, facials, and beauty transformations in Plantation, Florida — with a Brazilian touch.",bookBtn:"Book Appointment",navigate:"Navigate",servicesCol:"Services",findUs:"Find Us",copyright:"\xa9 ".concat(i," Blend Hair Boutique \xb7 All rights reserved \xb7 Plantation, Florida"),madeWith:"Made with love \xb7 Brazilian touch",serviceLinks:["Color & Balayage","Haircuts & Styling","Brazilian Blowout","Nails","Bridal & Events"],quickLinks:["Services","Gallery","Team","About","Contact","Gift Cards"]},teamData:[{specialty:"Co-Founder & Color Director",bio:"Fernanda is the visionary behind Blend Hair Boutique, bringing decades of Brazilian beauty expertise to Plantation, Florida. Her passion for color artistry, client connection, and creating a salon experience rooted in warmth and excellence defines everything Blend stands for.",languages:"English, Portuguese"},{specialty:"Co-Founder & Creative Director",bio:"Juliana co-founded Blend with a commitment to building a beauty space that feels as intentional as it is beautiful. Her vision for a boutique experience — personal, elevated, and genuine — is reflected in every detail of the salon.",languages:"English, Portuguese"},{specialty:"Senior Color & Style Specialist",bio:"With over 1,500 appointments and 99+ five-star reviews, Nana is one of Blend's most sought-after artists. Her expertise spans color, cuts, and smoothing treatments — all delivered with warmth, precision, and a deep understanding of each client's individuality.",languages:"English, Spanish, Portuguese"},{specialty:"Color Specialist & Senior Stylist",bio:"Roger brings exceptional technical skill and artistry to every appointment. With over 2,500 completed services and more than 1,100 loyal clients, his expertise in color and styling has made him one of Blend's most trusted and beloved professionals.",languages:"English"},{specialty:"Color & Style Artist",bio:"Debora's talent for color and styling has earned her nearly 1,000 completed appointments and a loyal base of over 400 clients. Known for her precision and genuine attention to detail, she transforms every visit into an experience worth returning for.",languages:"English"},{specialty:"Styling & Smoothing Specialist",bio:"Nilza's warm and attentive approach has earned her a perfect 5.0 rating from over 60 clients. Specializing in smoothing treatments and personalized styling, she creates results that are as effortless as they are beautiful.",languages:"Portuguese"},{specialty:"Balayage & Color Specialist",bio:"Ketty's eye for natural, dimensional color has made her a client favorite at Blend. Her expertise in balayage and highlighting techniques creates results that are luminous, modern, and always perfectly suited to each individual.",languages:"English, Portuguese"},{specialty:"Style & Blowout Specialist",bio:"Lea brings a refined touch to every style — from precision blowouts to polished everyday looks. Her dedication to making every client feel beautiful and confident shines through in every single service.",languages:"English"},{specialty:"Creative Stylist",bio:"Tabby's creative eye and technical precision make her one of Blend's most versatile stylists. Whether you're looking for a transformation or a refined update to your signature look, Tabby brings vision and artistry to every chair.",languages:"English"},{specialty:"Cut & Style Specialist",bio:"Edith combines technical precision with an intuitive sense of what works for each individual client. Her expertise in cuts and styling has earned her a perfect rating and a growing circle of dedicated, returning clients.",languages:"English, Spanish"},{specialty:"Color & Extensions Artist",bio:"Beatriz brings artistry and precision to color and extension services, helping clients achieve the length, volume, and dimension they've always dreamed of. Her meticulous approach and warmth create a truly personalized experience.",languages:"English, Portuguese"},{specialty:"Eyebrow Design Specialist",bio:"Adriana is Blend's resident brow artist, specializing in eyebrow design and shaping that perfectly frames each face. Her precision and attention to facial architecture create brows that are polished, natural, and uniquely tailored to each client.",languages:"English, Portuguese"},{specialty:"Esthetician & Laser Specialist",bio:"A licensed esthetician and laser technician, Fran helps clients feel confident through personalized facials and painless laser hair removal. Her clinical expertise and genuine passion for skin wellness create transformative results that go far beyond surface beauty.",languages:"English"}],pages:{services:{eyebrow:"Our Craft",h1:"Signature Services",sub:"Every service at Blend is a carefully designed experience — from the first conversation to the final result.",faqEyebrow:"FAQ",faqH2a:"Questions ",faqH2b:"Answered"},gallery:{eyebrow:"Our Work",h1a:"Beauty ",h1b:"Gallery"},team:{eyebrow:"The Artists",h1a:"Meet the ",h1b:"Beauty Team",sub:"Each member of the Blend team brings expertise, passion, and a deep commitment to personalized beauty.",languages:"Languages",bookBtn:"Book an Appointment"},about:{eyebrow:"Our Story",h1a:"Beauty Rooted in ",h1b:"Brazilian Heart",sub:"Blend Hair Boutique was created as a sanctuary for beauty, ritual, and connection — a space where artistry meets warmth, and every visit feels deeply personal.",storyEyebrow:"Who We Are",storyH2a:"A Boutique Built on ",storyH2b:"Connection",storyBody:["Rooted in Brazilian hospitality and inspired by modern luxury, Blend offers an experience designed to slow you down, restore confidence, and elevate everyday self-care into something intentional.","From dimensional color and precision cuts to restorative treatments and curated beauty services, every detail is approached with care, refinement, and an uncompromising commitment to quality.","As an Authorized K\xe9rastase Salon, we work exclusively with high-performance products trusted by some of the most respected professionals in the beauty industry. Our team combines technical expertise with an intuitive understanding of individuality — because no two guests, and no two transformations, are ever the same.","At Blend, beauty is never only about appearance. It is about how you feel when you walk back into the world."],storyBtn:"Book a Visit",valuesEyebrow:"Our Values",valuesH2a:"What Sets ",valuesH2b:"Blend Apart",values:[{title:"Brazilian-Inspired Hospitality",body:"Warmth, care, and genuine connection are at the heart of everything we do. Every client is welcomed like a guest in our home."},{title:"Personalized Beauty",body:"No two clients are alike. Every service begins with a thoughtful consultation to understand your hair, your life, and your vision."},{title:"Professional Excellence",body:"We invest in education, professional-grade products, and refined technique — because your results should always speak for themselves."}],communityEyebrow:"Our Community",communityH2a:"Proudly Serving ",communityH2b:"Plantation, Florida",communityBody:"Located in Plantation, Florida, Blend was thoughtfully designed to feel welcoming, calm, and effortlessly elevated. Whether you are preparing for a special occasion or simply carving out time for yourself, our purpose remains the same: to create an experience that leaves you feeling renewed, confident, and entirely cared for.",communityBook:"Book Appointment",communityCall:"Call Us",ctaEyebrow:"Come Experience Blend",ctaH2:"Your Beauty, Your Way.",ctaSub:"Custom beauty transformations designed around your hair, lifestyle, and confidence. In Plantation, Florida."},contact:{eyebrow:"Get in Touch",h1a:"We'd Love to ",h1b:"Hear From You",visitTitle:"Visit the Boutique",visitBody:"We're conveniently located in Plantation, Florida. Walk-ins welcome, but appointments are recommended.",formTitle:"Send a Message",formBody:"Questions? Special requests? We'll get back to you promptly.",formSentTitle:"Thank you for reaching out.",formSentBody:"We'll be in touch soon. In the meantime, feel free to book directly online.",fields:{name:"Your Name",namePlaceholder:"How should we address you?",email:"Email Address",emailPlaceholder:"Your email address",service:"Service of Interest",serviceOptions:["Hair Color & Balayage","Haircut & Styling","Brazilian Blowout & Keratin","Nails","Facials & Spa","Bridal & Events","Other"],message:"Message",messagePlaceholder:"Tell us what you're looking for...",submit:"Send via WhatsApp"},ctaEyebrow:"Ready to Begin?",ctaH2:"Book Your Appointment Today.",ctaSub:"The easiest way to experience Blend. Choose your service and time — we'll take care of the rest."}},mobileCta:{call:"Call",book:"Book",whatsapp:"WhatsApp"},mobileMenu:{bookBtn:"Book Appointment"}},pt:{announcement:"✦ Agendamentos abertos — agende online e confirme na hora \xb7 (754) 206-3501",nav:{services:"Servi\xe7os",gallery:"Galeria",team:"Equipe",about:"Sobre",location:"Contato",bookNow:"Agendar"},hero:{eyebrow:"Sal\xe3o Premium \xb7 Plantation, FL",h1:["Cabelos refinados,","com alma","brasileira."],sub:"Uma experi\xeancia boutique no cora\xe7\xe3o de Plantation. Nossas especialistas formadas no Brasil dominam colora\xe7\xe3o personalizada, tratamentos alisantes e cortes cl\xe1ssicos — com produtos K\xe9rastase e toda a hospitalidade brasileira.",cta1:"Agendar Hor\xe1rio",cta2:"Ligar (754) 206-3501",badge:"O sal\xe3o mais amado de Plantation",badgeSub:"1218 Avalia\xe7\xf5es Cinco Estrelas"},trustBar:["Sal\xe3o K\xe9rastase","Especialistas Brasileiras","Nota 5 Estrelas \xb7 1218 Avalia\xe7\xf5es","Desde 2012","Plantation, Florida"],services:{eyebrow:"Nossa Arte",h2a:"Servi\xe7os que ",h2b:"elevam",body:"Da colora\xe7\xe3o exclusiva aos tratamentos alisantes avan\xe7ados — cada servi\xe7o \xe9 pensado para o car\xe1ter \xfanico do seu cabelo.",viewAll:"Ver Todos os Servi\xe7os",bookNow:"Agendar →"},servicesData:[{category:"Colora\xe7\xe3o",title:"Colora\xe7\xe3o & Balayage",benefit:"Dimens\xe3o, profundidade e luminosidade feitos para o seu estilo de vida.",description:"Do balayage iluminado \xe0 colora\xe7\xe3o rica por inteiro — nossas coloristas criam f\xf3rmulas personalizadas para sua textura, tom de pele e rotina de manuten\xe7\xe3o.",detail:"Cada servi\xe7o de colora\xe7\xe3o come\xe7a com uma consulta completa para entender sua vis\xe3o e o hist\xf3rico do seu cabelo. Usamos linhas profissionais que protegem a integridade dos fios e garantem resultados vibrantes e duradouros.",priceNote:"Pre\xe7o inicial dispon\xedvel no momento do agendamento",badge:"Mais Solicitado"},{category:"Corte & Estilo",title:"Cortes & Finaliza\xe7\xe3o",benefit:"Um corte que funciona para o seu cabelo, a sua vida, a sua confian\xe7a.",description:"Cortes precisos, camadas naturais e finaliza\xe7\xe3o que valorizam o formato do seu rosto e exigem o m\xednimo de esfor\xe7o no dia a dia.",detail:"Cada corte come\xe7a com uma consulta a seco, avaliando a textura natural e o crescimento antes de qualquer tesoura. Finalizamos com um estilo que te mostra exatamente como recriar o look em casa.",priceNote:"Pre\xe7o inicial dispon\xedvel no momento do agendamento",badge:null},{category:"Tratamentos Alisantes",title:"Escova Brasileira & Queratina",benefit:"Cabelo sem frizz, liso e f\xe1cil de manejar por meses.",description:"Nossos tratamentos alisantes de inspira\xe7\xe3o brasileira eliminam o frizz, reduzem o tempo de secagem e deixam o cabelo incrivelmente liso, macio e saud\xe1vel.",detail:"Oferecemos uma linha de tratamentos de queratina e alisamento calibrados ao seu tipo de cabelo — de um alisamento suave para fios sens\xedveis a uma escova brasileira completa. Resultado dura de 3 a 5 meses.",priceNote:"Pre\xe7o inicial dispon\xedvel no momento do agendamento",badge:"Servi\xe7o Exclusivo"},{category:"Unhas",title:"Servi\xe7os de Unhas",benefit:"Unhas lindas e duradouras para completar o seu visual.",description:"Manicure, pedicure, gel e nail art. Nossas nail designers entregam resultados impec\xe1veis — cl\xe1ssicos atemporais ou designs arrojados.",detail:"Da manicure natural \xe0 nail art elaborada, usamos produtos profissionais e instrumentos higienizados. Servi\xe7os de gel incluem topcoat de longa dura\xe7\xe3o para brilho persistente.",priceNote:"Pre\xe7o inicial dispon\xedvel no momento do agendamento",badge:null},{category:"Pele & Spa",title:"Faciais & Spa",benefit:"Pele radiante e um momento de pura restaura\xe7\xe3o.",description:"Faciais personalizados, tratamentos hidratantes e rituais de spa para iluminar, equilibrar e restaurar o brilho natural da sua pele.",detail:"Nossos tratamentos de pele s\xe3o personalizados para o seu tipo e necessidades. Seja para opacidade, desidrata\xe7\xe3o ou simplesmente autocuidado — nossas esteticistas criam uma experi\xeancia sob medida.",priceNote:"Pre\xe7o inicial dispon\xedvel no momento do agendamento",badge:null},{category:"Depila\xe7\xe3o & Sobrancelhas",title:"Depila\xe7\xe3o & Design de Sobrancelha",benefit:"Sobrancelhas definidas e pele lisa que valorizam o seu rosto.",description:"Depila\xe7\xe3o corporal total e parcial, design e tingimento de sobrancelhas realizados com precis\xe3o e cuidado.",detail:"Usamos ceras premium adequadas para peles sens\xedveis. Todos os servi\xe7os de sobrancelha s\xe3o moldados para complementar a estrutura natural do seu rosto — o objetivo \xe9 sempre a sua melhor vers\xe3o.",priceNote:"Pre\xe7o inicial dispon\xedvel no momento do agendamento",badge:null},{category:"Alongamentos",title:"Alongamento de Cabelo",benefit:"Comprimento, volume e versatilidade instant\xe2neos.",description:"Apliques premium para um visual natural e integrado que se harmoniza perfeitamente com o seu pr\xf3prio cabelo.",detail:"Nossas especialistas trabalham com cabelo de alta qualidade e origem \xe9tica. Recomendamos o m\xe9todo mais adequado — cola, costura ou clipe — com orienta\xe7\xe3o de cuidados cont\xednuos.",priceNote:"Consulta obrigat\xf3ria — pre\xe7o varia conforme comprimento e m\xe9todo",badge:null},{category:"Noivas & Eventos",title:"Beleza para Noivas & Eventos",benefit:"Uma beleza inesquec\xedvel para os seus momentos mais importantes.",description:"Pacotes para noivas, estiliza\xe7\xe3o para eventos e prepara\xe7\xe3o de beleza para os dias que mais importam — cabelo, unhas e pele, tudo em um s\xf3 lugar.",detail:"Do noivado ao grande dia, oferecemos pacotes de beleza coordenados com ensaios, produ\xe7\xe3o no dia e servi\xe7os no local. Tamb\xe9m atendemos grupos de madrinhas.",priceNote:"Pacotes personalizados — agende uma consulta para noivas",badge:"Reserve com Anteced\xeancia"}],faqData:[{q:"Como fa\xe7o para agendar?",a:"Voc\xea pode agendar diretamente pelo nosso sistema online — dispon\xedvel 24 horas por dia, 7 dias por semana. Selecione o servi\xe7o, a profissional de sua prefer\xeancia e o hor\xe1rio. Para pacotes de noivas ou consultas, entre em contato conosco diretamente."},{q:"O que esperar na primeira visita?",a:"Toda nova cliente come\xe7a com uma consulta completa. Perguntamos sobre o hist\xf3rico do seu cabelo, rotina atual, estilo de vida e objetivos antes de recomendar qualquer servi\xe7o. Assim garantimos resultados feitos para voc\xea."},{q:"Quanto tempo dura um agendamento de balayage?",a:"Agendamentos de balayage geralmente levam de 2h30 a 4 horas, dependendo do comprimento, densidade e resultado desejado. Daremos uma estimativa realista no momento do agendamento ou consulta."},{q:"Voc\xeas oferecem vale-presente?",a:"Sim — oferecemos vale-presente em qualquer valor, perfeito para quem merece um toque de luxo. Podem ser adquiridos online ou no boutique."},{q:"Qual \xe9 a pol\xedtica de cancelamento?",a:"Pedimos pelo menos 24 horas de anteced\xeancia para cancelamentos ou remarca\xe7\xf5es. Cancelamentos tardios ou faltas podem estar sujeitos a uma taxa. Agradecemos sua compreens\xe3o — isso nos ajuda a atender todas as clientes."},{q:"Voc\xeas usam K\xe9rastase ou produtos de luxo?",a:"Trabalhamos com linhas profissionais de colora\xe7\xe3o e cuidados selecionadas pelo desempenho e sa\xfade dos fios. Ficamos felizes em recomendar produtos para uso em casa que complementem o tratamento no sal\xe3o."}],experience:{eyebrow:"A Experi\xeancia Blend",h2a:"Mais que um sal\xe3o —",h2b:"um ritual brasileiro.",body:"Entrar no Blend \xe9 diferente de qualquer outra visita a um sal\xe3o. Recebemos voc\xea com um expresso em porcelana fina, \xe1gua com g\xe1s e todo o calor da hospitalidade brasileira — porque beleza tem tudo a ver com como voc\xea se sente desde o momento em que chega.",highlights:["Ritual de boas-vindas: caf\xe9 e \xe1gua com g\xe1s ao chegar","Especialistas formadas no Brasil com mais de 10 anos de experi\xeancia","Produtos profissionais premium da K\xe9rastase","Consulta personalizada antes de cada servi\xe7o","Atendimento bil\xedngue — portugu\xeas e ingl\xeas"],cta1:"Conhe\xe7a a Equipe",cta2:"Nossa Hist\xf3ria"},gallery:{eyebrow:"Transforma\xe7\xf5es",h2a:"Trabalhos de que ",h2b:"nos orgulhamos",categories:["Todos","Colora\xe7\xe3o","Loiro","Castanho","Alisamento","Unhas","Noiva"],viewAll:"Ver Galeria Completa",placeholderNote:"As imagens da galeria s\xe3o ilustrativas — substitua pelas fotos reais do sal\xe3o.",labels:["Balayage Iluminado","Finaliza\xe7\xe3o Lisa","Colora\xe7\xe3o Castanho Rico","Nail Art","Mechas & Dimens\xe3o","Eleg\xe2ncia para Noiva","Cor Natural","Finaliza\xe7\xe3o & Estilo","Tratamento de Queratina","Alongamento & Volume","Facial Glow","Transforma\xe7\xe3o de Cor"],shortDescs:["Mechas pintadas \xe0 m\xe3o para um brilho natural e iluminado.","Volume sem frizz com acabamento polido de sal\xe3o.","Castanho profundo e multidimensional com reflexos quentes.","Designs de unhas artesanais para todos os estilos e ocasi\xf5es.","Mechas precisas em papel alum\xednio para dimens\xe3o luminosa em camadas.","Produ\xe7\xe3o nupcial impec\xe1vel para o seu dia mais especial.","Cor descomplicada que parece crescer naturalmente de forma intencional.","Secagem volumosa e lisa com modelagem profissional.","Queratina brasileira para eliminar o frizz por at\xe9 4 meses.","Alongamentos perfeitos para comprimento e volume imediatos.","Tratamento que potencializa a luminosidade da pele saud\xe1vel.","Transforma\xe7\xe3o completa de cor para o seu tom castanho ideal."],descs:["O balayage \xe9 uma t\xe9cnica de pintura \xe0 m\xe3o livre que cria reflexos suaves sem linhas marcadas. O crescimento fica lindo, tornando-o um dos servi\xe7os de colora\xe7\xe3o de menor manuten\xe7\xe3o dispon\xedveis.","Uma secagem profissional alisa a cut\xedcula, elimina o frizz e adiciona corpo e brilho duradouros. Usando produtos de prote\xe7\xe3o t\xe9rmica e t\xe9cnicas de secagem por tens\xe3o, criamos um acabamento que permanece fresco por dias.","Os servi\xe7os de colora\xe7\xe3o castanho usam f\xf3rmulas profissionais para construir profundidade rica e dimensional que captura a luz de forma bel\xedssima.","Do minimalismo clean aos detalhes pintados \xe0 m\xe3o, nossos servi\xe7os de unhas incluem esmalte em gel, nail art e alongamentos.","As mechas em papel alum\xednio criam dimens\xe3o precisa e luminosa por todo o cabelo — proporcionando brilho vis\xedvel e contraste marcante.","Os servi\xe7os para noiva come\xe7am com um agendamento de teste para finalizar o look perfeito. No dia, oferecemos estilo completo para a noiva e o grupo.","A cor natural imita a forma como o cabelo descolore naturalmente — lindamente. Uma t\xe9cnica de baixa manuten\xe7\xe3o com ra\xedzes sombreadas e pontas iluminadas.","Nossa secagem assinatura Blend combina s\xe9runs de prote\xe7\xe3o t\xe9rmica, secagem por tens\xe3o e modelagem com escova redonda para corpo duradouro e acabamento espelhado.","O tratamento profissional de queratina brasileira infunde prote\xedna nas profundezas do fio, selando a cut\xedcula e eliminando o frizz dramaticamente.","Nossos servi\xe7os de alongamento adicionam comprimento e densidade naturais sem danificar o seu cabelo existente.","Um tratamento facial restaurador com foco em hidrata\xe7\xe3o, textura e luminosidade usando s\xe9runs de n\xedvel cl\xednico.","Um servi\xe7o completo de transforma\xe7\xe3o de cor — da consulta aprofundada \xe0 revela\xe7\xe3o final."],statsLabels:["Avalia\xe7\xf5es no Google","Nota no Google","Anos de Arte","Arte Brasileira"],baSection:{eyebrow:"A Diferen\xe7a Blend",h2a:"Antes & ",h2b:"Depois",sub:"Arraste para revelar a transforma\xe7\xe3o. Resultados reais, clientes reais.",before:"Antes",after:"Depois"},baPairs:["Castanho a Balayage","Frizz a Seda","Dia a Dia a Noiva"],editorial:{eyebrow:"Criado pelos Artistas do Blend",h2a:"Cada resultado \xe9 uma ",h2b:"colabora\xe7\xe3o.",sub:"Cada transforma\xe7\xe3o come\xe7a com uma conversa — entendendo o seu cabelo, a sua vida e a sua vis\xe3o.",cta:"Agende Sua Transforma\xe7\xe3o"},testimonial:{eyebrow:"Hist\xf3ria da Cliente",quote:"J\xe1 fui a muitos sal\xf5es no Sul da Fl\xf3rida e o Blend \xe9 simplesmente outro n\xedvel. Meu balayage ficou naturalmente impec\xe1vel e a cor durou muito tempo. Finalmente encontrei meu sal\xe3o.",author:"Mariana T. \xb7 Balayage"}},reviews:{eyebrow:"Amor das Clientes",h2a:"O que nossas clientes ",h2b:"dizem",body:"Palavras reais de quem temos o privil\xe9gio de atender.",googleRating:"Avalia\xe7\xf5es no Google"},reviewsData:[{quote:"J\xe1 fui a muitos sal\xf5es no Sul da Fl\xf3rida e o Blend \xe9 simplesmente outro n\xedvel. Meu balayage ficou naturalmente impec\xe1vel e a cor durou muito tempo. Finalmente encontrei meu sal\xe3o.",author:"Mariana T.",service:"Balayage"},{quote:"A escova brasileira aqui \xe9 a melhor que j\xe1 fiz. Meu cabelo nunca esteve t\xe3o liso, mesmo com a umidade da Fl\xf3rida. Toda a experi\xeancia pareceu um boutique de luxo.",author:"Sophia R.",service:"Escova Brasileira"},{quote:"Elas realmente ouvem. Cheguei nervosa com uma grande mudan\xe7a e sa\xed me sentindo a melhor vers\xe3o de mim mesma. S\xf3 a consulta j\xe1 valeu a visita.",author:"Jennifer L.",service:"Corte & Estilo"}],cta:{eyebrow:"Comece a Jornada",h2:"Pronta para a Sua Transforma\xe7\xe3o?",sub:"Cada visita ao Blend \xe9 um passo em dire\xe7\xe3o \xe0 vers\xe3o mais linda e confiante de voc\xea. Agende hoje.",book:"Agendar Hor\xe1rio",secondary:"Fale Conosco"},contact:{eyebrow:"Onde Estamos",h2a:"Venha Visitar ",h2b:"o Blend",body:"Estamos no cora\xe7\xe3o de Plantation, Fl\xf3rida — f\xe1cil de encontrar, imposs\xedvel de esquecer.",address:"Endere\xe7o",phone:"Telefone",whatsapp:"WhatsApp",whatsappLink:"Mande uma mensagem",email:"E-mail",instagram:"Instagram",hours:"Hor\xe1rios"},footer:{tagline:"Colora\xe7\xe3o de luxo, tratamentos alisantes, unhas, faciais e transforma\xe7\xf5es de beleza em Plantation, Fl\xf3rida — com toque brasileiro.",bookBtn:"Agendar Hor\xe1rio",navigate:"Navegar",servicesCol:"Servi\xe7os",findUs:"Encontre-nos",copyright:"\xa9 ".concat(i," Blend Hair Boutique \xb7 Todos os direitos reservados \xb7 Plantation, Florida"),madeWith:"Feito com amor \xb7 toque brasileiro",serviceLinks:["Colora\xe7\xe3o & Balayage","Cortes & Finaliza\xe7\xe3o","Escova Brasileira","Unhas","Noivas & Eventos"],quickLinks:["Servi\xe7os","Galeria","Equipe","Sobre","Contato","Vale-Presente"]},teamData:[{specialty:"Co-fundadora & Diretora de Colora\xe7\xe3o",bio:"Fernanda \xe9 a vision\xe1ria por tr\xe1s do Blend Hair Boutique, trazendo d\xe9cadas de expertise em beleza brasileira para Plantation, Florida. Sua paix\xe3o pela arte da colora\xe7\xe3o, a conex\xe3o com os clientes e a cria\xe7\xe3o de uma experi\xeancia de sal\xe3o baseada em acolhimento e excel\xeancia define tudo o que o Blend representa.",languages:"Ingl\xeas, Portugu\xeas"},{specialty:"Co-fundadora & Diretora Criativa",bio:"Juliana co-fundou o Blend com o compromisso de construir um espa\xe7o de beleza t\xe3o intencional quanto belo. Sua vis\xe3o para uma experi\xeancia boutique — pessoal, elevada e genu\xedna — se reflete em cada detalhe do sal\xe3o.",languages:"Ingl\xeas, Portugu\xeas"},{specialty:"Especialista S\xeanior em Cor e Estilo",bio:"Com mais de 1.500 atendimentos e 99+ avalia\xe7\xf5es cinco estrelas, Nana \xe9 uma das artistas mais procuradas do Blend. Sua expertise abrange colora\xe7\xe3o, cortes e tratamentos alisantes — sempre com calor humano, precis\xe3o e profundo entendimento da individualidade de cada cliente.",languages:"Ingl\xeas, Espanhol, Portugu\xeas"},{specialty:"Especialista em Cor & Estilista S\xeanior",bio:"Roger traz habilidade t\xe9cnica e criatividade excepcionais a cada atendimento. Com mais de 2.500 servi\xe7os realizados e mais de 1.100 clientes fi\xe9is, sua expertise em colora\xe7\xe3o e estilo o tornou um dos profissionais mais admirados do Blend.",languages:"Ingl\xeas"},{specialty:"Artista em Cor e Estilo",bio:"O talento de Debora para colora\xe7\xe3o e estilo rendeu quase 1.000 atendimentos e uma base fiel de mais de 400 clientes. Conhecida pela sua precis\xe3o e aten\xe7\xe3o genu\xedna aos detalhes, ela transforma cada visita em uma experi\xeancia pela qual vale a pena voltar.",languages:"Ingl\xeas"},{specialty:"Especialista em Estilo e Alisamento",bio:"A abordagem calorosa e atenta de Nilza lhe rendeu uma avalia\xe7\xe3o perfeita de 5.0 com mais de 60 clientes. Especializada em tratamentos alisantes e estilo personalizado, ela cria resultados t\xe3o naturais quanto incr\xedveis.",languages:"Portugu\xeas"},{specialty:"Especialista em Balayage & Colora\xe7\xe3o",bio:"O olhar de Ketty para cores naturais e dimensionais a tornou uma das favoritas dos clientes no Blend. Sua expertise em t\xe9cnicas de balayage e luzes cria resultados luminosos, modernos e sempre perfeitamente adequados a cada pessoa.",languages:"Ingl\xeas, Portugu\xeas"},{specialty:"Especialista em Estilo & Secagem",bio:"Lea traz um toque refinado a cada estilo — de secagens precisas a looks polidos para o dia a dia. Sua dedica\xe7\xe3o em fazer cada cliente se sentir bonita e confiante transparece em cada atendimento.",languages:"Ingl\xeas"},{specialty:"Estilista Criativa",bio:"O olhar criativo e a precis\xe3o t\xe9cnica de Tabby fazem dela uma das estilistas mais vers\xe1teis do Blend. Seja para uma transforma\xe7\xe3o completa ou uma atualiza\xe7\xe3o refinada do seu look, Tabby traz vis\xe3o e criatividade a cada cadeira.",languages:"Ingl\xeas"},{specialty:"Especialista em Corte e Estilo",bio:"Edith combina precis\xe3o t\xe9cnica com uma percep\xe7\xe3o intuitiva do que funciona para cada cliente. Sua expertise em cortes e estilo lhe rendeu uma avalia\xe7\xe3o perfeita e um c\xedrculo crescente de clientes dedicados.",languages:"Ingl\xeas, Espanhol"},{specialty:"Artista em Cor & Alongamentos",bio:"Beatriz traz criatividade e precis\xe3o aos servi\xe7os de colora\xe7\xe3o e alongamentos, ajudando os clientes a alcan\xe7ar o comprimento, volume e dimens\xe3o que sempre sonharam. Sua abordagem meticulosa e calor humano criam uma experi\xeancia verdadeiramente personalizada.",languages:"Ingl\xeas, Portugu\xeas"},{specialty:"Especialista em Design de Sobrancelhas",bio:"Adriana \xe9 a artista de sobrancelhas do Blend, especializada em design e modelagem que enquadra perfeitamente cada rosto. Sua precis\xe3o e aten\xe7\xe3o \xe0 arquitetura facial criam sobrancelhas polidas, naturais e exclusivamente adaptadas a cada cliente.",languages:"Ingl\xeas, Portugu\xeas"},{specialty:"Esteticista & Especialista em Laser",bio:"Esteticista licenciada e t\xe9cnica em laser, Fran ajuda os clientes a se sentirem confiantes por meio de faciais personalizados e remo\xe7\xe3o de pelos a laser sem dor. Sua expertise cl\xednica e paix\xe3o genu\xedna pelo bem-estar da pele criam resultados transformadores que v\xe3o muito al\xe9m da beleza superficial.",languages:"Ingl\xeas"}],pages:{services:{eyebrow:"Nossa Arte",h1:"Servi\xe7os Exclusivos",sub:"Cada servi\xe7o no Blend \xe9 uma experi\xeancia cuidadosamente elaborada — da primeira conversa ao resultado final.",faqEyebrow:"Perguntas Frequentes",faqH2a:"Perguntas ",faqH2b:"Respondidas"},gallery:{eyebrow:"Nosso Trabalho",h1a:"Galeria de ",h1b:"Beleza"},team:{eyebrow:"As Artistas",h1a:"Conhe\xe7a a ",h1b:"Equipe de Beleza",sub:"Cada membro da equipe Blend traz expertise, paix\xe3o e um profundo comprometimento com a beleza personalizada.",languages:"Idiomas",bookBtn:"Agendar Hor\xe1rio"},about:{eyebrow:"Nossa Hist\xf3ria",h1a:"Beleza com ",h1b:"Alma Brasileira",sub:"O Blend Hair Boutique nasceu do amor pela beleza, do comprometimento com o of\xedcio e da tradi\xe7\xe3o brasileira de hospitalidade genu\xedna e sem pressa.",storyEyebrow:"Quem Somos",storyH2a:"Um Boutique Constru\xeddo na ",storyH2b:"Conex\xe3o",storyBody:["Blend Hair Boutique \xe9 um sal\xe3o e boutique de beleza completo em Plantation, Fl\xf3rida. Reunimos o calor brasileiro e a t\xe9cnica de padr\xe3o mundial sob o mesmo teto.","Nossos servi\xe7os abrangem colora\xe7\xe3o, balayage, tratamentos alisantes, cortes e finaliza\xe7\xf5es, unhas, faciais, spa, depila\xe7\xe3o e beleza para noivas e eventos — tudo pensado para o indiv\xedduo, n\xe3o para um modelo padr\xe3o.","Acreditamos que beleza \xe9 pessoal. Cada visita come\xe7a com uma conversa, n\xe3o com suposi\xe7\xf5es. Tomamos o tempo para entender o seu cabelo, o seu estilo de vida e a sua vis\xe3o — e ent\xe3o criamos algo que parece inegavelmente com voc\xea."],storyBtn:"Agendar uma Visita",valuesEyebrow:"Nossos Valores",valuesH2a:"O que nos torna ",valuesH2b:"\xfanicos",values:[{title:"Hospitalidade Brasileira",body:"Calor humano, cuidado e conex\xe3o genu\xedna est\xe3o no cora\xe7\xe3o de tudo o que fazemos. Cada cliente \xe9 recebida como uma convidada em nossa casa."},{title:"Beleza Personalizada",body:"Duas clientes n\xe3o s\xe3o iguais. Cada servi\xe7o come\xe7a com uma consulta atenta para entender o seu cabelo, a sua vida e a sua vis\xe3o."},{title:"Excel\xeancia Profissional",body:"Investimos em educa\xe7\xe3o, produtos profissionais e t\xe9cnica refinada — porque o resultado deve sempre falar por si mesmo."}],communityEyebrow:"Nossa Comunidade",communityH2a:"Com orgulho em ",communityH2b:"Plantation, Florida",communityBody:"O Blend Hair Boutique faz parte da comunidade de Plantation — e nossas clientes s\xe3o nossas vizinhas, amigas, fam\xedlia estendida. Temos a honra de fazer parte de suas vidas e transforma\xe7\xf5es.",communityBook:"Agendar Hor\xe1rio",communityCall:"Ligar",ctaEyebrow:"Venha Viver o Blend",ctaH2:"Sua Beleza, do Seu Jeito.",ctaSub:"Transforma\xe7\xf5es de beleza personalizadas pensadas para o seu cabelo, estilo de vida e confian\xe7a. Em Plantation, Fl\xf3rida."},contact:{eyebrow:"Fale Conosco",h1a:"Adorar\xedamos ",h1b:"Ouvir de Voc\xea",visitTitle:"Visite o Boutique",visitBody:"Estamos convenientemente localizados em Plantation, Fl\xf3rida. Aceitamos clientes sem agendamento, mas recomendamos uma reserva.",formTitle:"Envie uma Mensagem",formBody:"D\xfavidas? Pedidos especiais? Retornaremos em breve.",formSentTitle:"Obrigada por entrar em contato.",formSentBody:"Retornaremos em breve. Enquanto isso, fique \xe0 vontade para agendar diretamente online.",fields:{name:"Seu Nome",namePlaceholder:"Como podemos te chamar?",email:"E-mail",emailPlaceholder:"Seu endere\xe7o de e-mail",service:"Servi\xe7o de Interesse",serviceOptions:["Colora\xe7\xe3o & Balayage","Corte & Finaliza\xe7\xe3o","Escova Brasileira & Queratina","Unhas","Faciais & Spa","Noivas & Eventos","Outro"],message:"Mensagem",messagePlaceholder:"Conte o que voc\xea est\xe1 procurando...",submit:"Enviar via WhatsApp"},ctaEyebrow:"Pronta para Come\xe7ar?",ctaH2:"Agende o Seu Hor\xe1rio Hoje.",ctaSub:"A forma mais f\xe1cil de viver o Blend. Escolha o servi\xe7o e o hor\xe1rio — cuidamos do resto."}},mobileCta:{call:"Ligar",book:"Agendar",whatsapp:"WhatsApp"},mobileMenu:{bookBtn:"Agendar Hor\xe1rio"}},es:{announcement:"✦ Reservas abiertas — reserva en l\xednea para confirmaci\xf3n inmediata \xb7 (754) 206-3501",nav:{services:"Servicios",gallery:"Galer\xeda",team:"Equipo",about:"Nosotros",location:"Contacto",bookNow:"Reservar"},hero:{eyebrow:"Sal\xf3n Premium \xb7 Plantation, FL",h1:["Cabello refinado,","con alma","brasile\xf1a."],sub:"Una experiencia boutique en el coraz\xf3n de Plantation. Nuestras especialistas formadas en Brasil dominan el color personalizado, tratamientos alisadores y cortes atemporales — con productos K\xe9rastase y la c\xe1lida hospitalidad brasile\xf1a.",cta1:"Reservar Cita",cta2:"Llamar (754) 206-3501",badge:"El sal\xf3n m\xe1s querido de Plantation",badgeSub:"1218 Rese\xf1as de Cinco Estrellas"},trustBar:["Sal\xf3n K\xe9rastase","Especialistas Brasile\xf1as","Calificaci\xf3n 5 Estrellas \xb7 1218 Rese\xf1as","Desde 2012","Plantation, Florida"],services:{eyebrow:"Nuestro Arte",h2a:"Servicios que ",h2b:"elevan",body:"Desde la coloraci\xf3n exclusiva hasta los tratamientos alisadores avanzados — cada servicio est\xe1 pensado para el car\xe1cter \xfanico de tu cabello.",viewAll:"Ver Todos los Servicios",bookNow:"Reservar →"},servicesData:[{category:"Coloraci\xf3n",title:"Coloraci\xf3n & Balayage",benefit:"Dimensi\xf3n, profundidad y luminosidad dise\xf1adas para tu estilo de vida.",description:"Desde el balayage iluminado hasta la coloraci\xf3n completa — nuestras coloristas crean f\xf3rmulas personalizadas seg\xfan tu textura, tono de piel y rutina de mantenimiento.",detail:"Cada servicio de color comienza con una consulta completa. Usamos l\xedneas de color profesionales que protegen la integridad del cabello y entregan resultados vibrantes y duraderos.",priceNote:"Precio inicial disponible al momento de la reserva",badge:"El M\xe1s Solicitado"},{category:"Corte & Estilo",title:"Cortes & Estilizado",benefit:"Un corte que funciona para tu cabello, tu vida, tu confianza.",description:"Cortes de precisi\xf3n, capas naturales y estilizado que favorecen la forma de tu rostro y requieren el m\xednimo esfuerzo diario.",detail:"Cada corte comienza con una consulta en seco, evaluando la textura natural y el crecimiento antes del primer corte. Terminamos con un estilo que te muestra c\xf3mo recrear el look en casa.",priceNote:"Precio inicial disponible al momento de la reserva",badge:null},{category:"Tratamientos Alisadores",title:"Brushing Brasile\xf1o & Keratina",benefit:"Cabello sin frizz, liso y manejable durante meses.",description:"Nuestros tratamientos alisadores de inspiraci\xf3n brasile\xf1a eliminan el frizz, reducen el tiempo de secado y dejan el cabello brillantemente liso, suave y saludable.",detail:"Ofrecemos una gama de tratamientos de keratina y alisado calibrados a tu tipo de cabello — desde un alisado suave hasta un brushing brasile\xf1o completo. Los resultados duran de 3 a 5 meses.",priceNote:"Precio inicial disponible al momento de la reserva",badge:"Servicio Exclusivo"},{category:"U\xf1as",title:"Servicios de U\xf1as",benefit:"U\xf1as hermosas y duraderas para completar tu look.",description:"Manicure, pedicure, gel y nail art. Nuestras nail artists entregan resultados impecables, ya sea cl\xe1sicos atemporales o dise\xf1os llamativos.",detail:"Desde un manicure natural hasta nail art intrincado, usamos productos profesionales e instrumentos higienizados. Los servicios de gel incluyen topcoat de larga duraci\xf3n.",priceNote:"Precio inicial disponible al momento de la reserva",badge:null},{category:"Piel & Spa",title:"Faciales & Spa",benefit:"Piel radiante y un momento de pura restauraci\xf3n.",description:"Faciales personalizados, tratamientos hidratantes y rituales de spa dise\xf1ados para iluminar, equilibrar y restaurar el resplandor natural de tu piel.",detail:"Nuestros tratamientos se personalizan seg\xfan tu tipo de piel y necesidades. Ya sea opacidad, deshidrataci\xf3n o un momento de autocuidado, nuestras esteticistas crean una experiencia a tu medida.",priceNote:"Precio inicial disponible al momento de la reserva",badge:null},{category:"Depilaci\xf3n & Cejas",title:"Depilaci\xf3n & Dise\xf1o de Cejas",benefit:"Cejas definidas y piel suave que enmarcan tus rasgos.",description:"Depilaci\xf3n corporal total y parcial, dise\xf1o y tinte de cejas realizados con precisi\xf3n y cuidado.",detail:"Usamos ceras premium adecuadas para pieles sensibles. Todos los servicios de cejas se dise\xf1an para complementar la estructura natural de tu rostro.",priceNote:"Precio inicial disponible al momento de la reserva",badge:null},{category:"Extensiones",title:"Extensiones de Cabello",benefit:"Largo, volumen y versatilidad instant\xe1neos.",description:"Extensiones de cabello premium aplicadas para un look natural y uniforme que se integra perfectamente con tu cabello.",detail:"Nuestras especialistas trabajan con cabello de alta calidad y origen \xe9tico. Recomendamos el m\xe9todo m\xe1s adecuado para tu tipo de cabello y estilo de vida.",priceNote:"Consulta obligatoria — el precio var\xeda seg\xfan el largo y m\xe9todo",badge:null},{category:"Novias & Eventos",title:"Belleza para Novias & Eventos",benefit:"Una belleza inolvidable para tus momentos m\xe1s importantes.",description:"Paquetes para novias, estilizado para eventos y preparaci\xf3n de belleza para los d\xedas que m\xe1s importan — cabello, u\xf1as y piel, todo en un boutique.",detail:"Desde el compromiso hasta el gran d\xeda, ofrecemos paquetes de belleza coordinados con ensayos, producci\xf3n el d\xeda del evento y servicios en el lugar.",priceNote:"Paquetes personalizados — reserva una consulta para novias",badge:"Reserva con Anticipaci\xf3n"}],faqData:[{q:"\xbfC\xf3mo reservo una cita?",a:"Puedes reservar directamente en l\xednea a trav\xe9s de nuestro sistema de reservas — disponible 24/7. Selecciona el servicio, la especialista de tu preferencia y el horario. Para paquetes de novias o consultas, cont\xe1ctanos directamente."},{q:"\xbfQu\xe9 debo esperar en mi primera visita?",a:"Cada nueva clienta comienza con una consulta completa. Preguntamos sobre el historial de tu cabello, rutina actual, estilo de vida y objetivos antes de recomendar cualquier servicio."},{q:"\xbfCu\xe1nto tiempo dura una cita de balayage?",a:"Las citas de balayage generalmente duran entre 2.5 y 4 horas seg\xfan el largo, densidad y resultado deseado. Te daremos una estimativa realista al momento de la reserva o consulta."},{q:"\xbfOfrecen tarjetas de regalo?",a:"S\xed — ofrecemos tarjetas de regalo en cualquier monto, perfectas para quienes merecen un toque de lujo. Se pueden adquirir en l\xednea o en el boutique."},{q:"\xbfCu\xe1l es la pol\xedtica de cancelaci\xf3n?",a:"Pedimos al menos 24 horas de anticipaci\xf3n para cancelaciones o cambios de horario. Las cancelaciones tard\xedas o ausencias pueden estar sujetas a un cargo. Agradecemos tu comprensi\xf3n."},{q:"\xbfUsan K\xe9rastase u otros productos de lujo?",a:"Trabajamos con l\xedneas profesionales de coloraci\xf3n y cuidado seleccionadas por su rendimiento y beneficio capilar. Siempre estamos felices de recomendar productos para el hogar que complementen tu tratamiento."}],experience:{eyebrow:"La Experiencia Blend",h2a:"M\xe1s que un sal\xf3n —",h2b:"un ritual brasile\xf1o.",body:"Entrar al Blend es diferente a cualquier otra visita a un sal\xf3n. Te recibimos con un espresso en porcelana fina, agua con gas y el calor de la hospitalidad brasile\xf1a — porque la belleza tiene que ver con c\xf3mo te sientes desde el momento en que llegas.",highlights:["Ritual de bienvenida: espresso & agua con gas al llegar","Especialistas formadas en Brasil con m\xe1s de 10 a\xf1os de experiencia","Productos profesionales premium de K\xe9rastase","Consulta personalizada antes de cada servicio","Atenci\xf3n biling\xfce — espa\xf1ol e ingl\xe9s"],cta1:"Conoce al Equipo",cta2:"Nuestra Historia"},gallery:{eyebrow:"Transformaciones",h2a:"Trabajos de los que ",h2b:"nos enorgullecemos",categories:["Todos","Color","Rubio","Casta\xf1o","Alisado","U\xf1as","Novia"],viewAll:"Ver Galer\xeda Completa",placeholderNote:"Las im\xe1genes de la galer\xeda son ilustrativas — reempl\xe1zalas con fotograf\xedas reales del sal\xf3n.",labels:["Balayage Iluminado","Alisado Perfecto","Color Casta\xf1o Rico","Nail Art","Mechas & Dimensi\xf3n","Elegancia para Novia","Color Natural","Alisado & Estilo","Tratamiento de Keratina","Extensiones & Volumen","Facial Luminoso","Transformaci\xf3n de Color"],shortDescs:["Mechas pintadas a mano para un brillo natural e iluminado.","Volumen sin frizz con un acabado pulido de sal\xf3n.","Casta\xf1o profundo y multidimensional con tonos c\xe1lidos.","Dise\xf1os de u\xf1as artesanales para todos los estilos y ocasiones.","Mechas precisas en papel de aluminio para una dimensi\xf3n luminosa en capas.","Estilismo nupcial impecable adaptado a tu d\xeda m\xe1s especial.","Color sin esfuerzo que parece crecer de forma intencionalmente natural.","Brushing voluminoso y liso con modelado experto.","Keratina brasile\xf1a para eliminar el frizz por hasta 4 meses.","Extensiones perfectas para largo y volumen instant\xe1neos.","Tratamiento que potencia la luminosidad de la piel saludable.","Cambio completo de color hacia tu tono casta\xf1o perfecto."],descs:["El balayage es una t\xe9cnica de pintura a mano alzada que crea reflejos suaves sin l\xedneas marcadas. El crecimiento queda precioso, convirti\xe9ndolo en uno de los servicios de coloraci\xf3n de menor mantenimiento disponibles.","Un brushing profesional suaviza la cut\xedcula, elimina el frizz y a\xf1ade cuerpo y brillo duraderos. Con productos de protecci\xf3n t\xe9rmica y t\xe9cnicas expertas, creamos un acabado que dura d\xedas.","Los servicios de coloraci\xf3n casta\xf1o utilizan f\xf3rmulas profesionales para construir una profundidad rica y dimensional que captura la luz de forma hermosa.","Desde el minimalismo limpio hasta el detalle pintado a mano, nuestros servicios de u\xf1as incluyen esmalte gel, nail art y extensiones.","El mecheado en papel de aluminio crea una dimensi\xf3n precisa y luminosa en todo el cabello — d\xe1ndote brillo visible y contraste llamativo.","Los servicios nupciales comienzan con una cita de prueba para finalizar tu look perfecto. El d\xeda del evento, ofrecemos estilismo completo para la novia y el grupo.","El color natural imita la forma en que el cabello se aclara de forma natural — de manera hermosa. Una t\xe9cnica de bajo mantenimiento con ra\xedces sombreadas y puntas sutilmente iluminadas.","Nuestro brushing signature Blend combina s\xe9rums de protecci\xf3n t\xe9rmica, secado por tensi\xf3n y modelado con cepillo redondo para lograr cuerpo duradero y acabado espejado.","Un tratamiento profesional de alisado con keratina brasile\xf1a infunde prote\xedna en el eje del cabello, sellando la cut\xedcula y eliminando dram\xe1ticamente el frizz.","Nuestros servicios de extensiones a\xf1aden largo y densidad naturales sin da\xf1ar tu cabello existente.","Un tratamiento facial restaurador que trabaja la hidrataci\xf3n, la textura y la luminosidad usando s\xe9rums de nivel cl\xednico.","Un servicio completo de transformaci\xf3n de color — desde la consulta en profundidad hasta la revelaci\xf3n final."],statsLabels:["Rese\xf1as en Google","Nota en Google","A\xf1os de Arte","Arte Brasile\xf1o"],baSection:{eyebrow:"La Diferencia Blend",h2a:"Antes & ",h2b:"Despu\xe9s",sub:"Arrastra para revelar la transformaci\xf3n. Resultados reales, clientas reales.",before:"Antes",after:"Despu\xe9s"},baPairs:["Casta\xf1o a Balayage","Frizz a Seda","D\xeda a D\xeda a Novia"],editorial:{eyebrow:"Creado por los Artistas de Blend",h2a:"Cada resultado es una ",h2b:"colaboraci\xf3n.",sub:"Cada transformaci\xf3n comienza con una conversaci\xf3n — entendiendo tu cabello, tu vida y tu visi\xf3n.",cta:"Reserva Tu Transformaci\xf3n"},testimonial:{eyebrow:"Historia de Clienta",quote:"He ido a muchos salones en el sur de Florida y Blend simplemente est\xe1 en otro nivel. Mi balayage qued\xf3 naturalmente impecable y el color dur\xf3 much\xedsimo. Por fin encontr\xe9 mi sal\xf3n.",author:"Mariana T. \xb7 Balayage"}},reviews:{eyebrow:"Lo que dicen",h2a:"Lo que nuestras clientas ",h2b:"opinan",body:"Palabras reales de las personas a las que tenemos el privilegio de atender.",googleRating:"Rese\xf1as en Google"},reviewsData:[{quote:"He ido a muchos salones en el sur de Florida y Blend simplemente est\xe1 en otro nivel. Mi balayage qued\xf3 naturalmente impecable y el color dur\xf3 much\xedsimo. Por fin encontr\xe9 mi sal\xf3n.",author:"Mariana T.",service:"Balayage"},{quote:"El brushing brasile\xf1o aqu\xed es el mejor que he tenido. Mi cabello nunca hab\xeda estado tan liso, incluso con la humedad de Florida. Toda la experiencia se sinti\xf3 como un boutique de lujo.",author:"Sophia R.",service:"Brushing Brasile\xf1o"},{quote:"Realmente escuchan. Llegu\xe9 nerviosa por un gran cambio y sal\xed sinti\xe9ndome la mejor versi\xf3n de m\xed misma. Solo la consulta ya vali\xf3 la visita.",author:"Jennifer L.",service:"Corte & Estilo"}],cta:{eyebrow:"Comienza Tu Viaje",h2:"\xbfLista para Tu Transformaci\xf3n?",sub:"Cada visita a Blend es un paso hacia la versi\xf3n m\xe1s bella y segura de ti. Reserva tu cita hoy.",book:"Reservar Cita",secondary:"Cont\xe1ctanos"},contact:{eyebrow:"Encu\xe9ntranos",h2a:"Ven a Visitar ",h2b:"el Blend",body:"Estamos en el coraz\xf3n de Plantation, Florida — f\xe1cil de encontrar, imposible de olvidar.",address:"Direcci\xf3n",phone:"Tel\xe9fono",whatsapp:"WhatsApp",whatsappLink:"Env\xedanos un mensaje",email:"Correo electr\xf3nico",instagram:"Instagram",hours:"Horarios"},footer:{tagline:"Coloraci\xf3n de lujo, tratamientos alisadores, u\xf1as, faciales y transformaciones de belleza en Plantation, Florida — con toque brasile\xf1o.",bookBtn:"Reservar Cita",navigate:"Navegar",servicesCol:"Servicios",findUs:"Encu\xe9ntranos",copyright:"\xa9 ".concat(i," Blend Hair Boutique \xb7 Todos los derechos reservados \xb7 Plantation, Florida"),madeWith:"Hecho con amor \xb7 toque brasile\xf1o",serviceLinks:["Coloraci\xf3n & Balayage","Cortes & Estilizado","Brushing Brasile\xf1o","U\xf1as","Novias & Eventos"],quickLinks:["Servicios","Galer\xeda","Equipo","Nosotros","Contacto","Tarjetas de Regalo"]},teamData:[{specialty:"Cofundadora & Directora de Color",bio:"Fernanda es la visionaria detr\xe1s de Blend Hair Boutique, aportando d\xe9cadas de experiencia en belleza brasile\xf1a a Plantation, Florida. Su pasi\xf3n por el arte del color, la conexi\xf3n con los clientes y la creaci\xf3n de una experiencia de sal\xf3n basada en la calidez y la excelencia define todo lo que Blend representa.",languages:"Ingl\xe9s, Portugu\xe9s"},{specialty:"Cofundadora & Directora Creativa",bio:"Juliana cofund\xf3 Blend con el compromiso de construir un espacio de belleza tan intencional como hermoso. Su visi\xf3n para una experiencia boutique — personal, elevada y genuina — se refleja en cada detalle del sal\xf3n.",languages:"Ingl\xe9s, Portugu\xe9s"},{specialty:"Especialista Senior en Color y Estilo",bio:"Con m\xe1s de 1.500 citas y 99+ rese\xf1as de cinco estrellas, Nana es una de las artistas m\xe1s solicitadas de Blend. Su expertise abarca color, cortes y tratamientos alisadores — siempre con calidez, precisi\xf3n y una profunda comprensi\xf3n de la individualidad de cada cliente.",languages:"Ingl\xe9s, Espa\xf1ol, Portugu\xe9s"},{specialty:"Especialista en Color & Estilista Senior",bio:"Roger aporta habilidad t\xe9cnica y creatividad excepcionales a cada cita. Con m\xe1s de 2.500 servicios completados y m\xe1s de 1.100 clientes fieles, su expertise en color y estilismo lo ha convertido en uno de los profesionales m\xe1s admirados de Blend.",languages:"Ingl\xe9s"},{specialty:"Artista en Color y Estilo",bio:"El talento de Debora para el color y el estilismo le ha valido casi 1.000 citas completadas y una base fiel de m\xe1s de 400 clientes. Conocida por su precisi\xf3n y atenci\xf3n genuina al detalle, convierte cada visita en una experiencia a la que vale la pena volver.",languages:"Ingl\xe9s"},{specialty:"Especialista en Estilo y Alisado",bio:"El enfoque c\xe1lido y atento de Nilza le ha valido una calificaci\xf3n perfecta de 5.0 con m\xe1s de 60 clientes. Especializada en tratamientos alisadores y estilismo personalizado, crea resultados tan naturales como impresionantes.",languages:"Portugu\xe9s"},{specialty:"Especialista en Balayage & Color",bio:"El ojo de Ketty para los colores naturales y dimensionales la ha convertido en una de las favoritas de los clientes en Blend. Su expertise en t\xe9cnicas de balayage e iluminaci\xf3n crea resultados luminosos, modernos y siempre perfectamente adaptados a cada persona.",languages:"Ingl\xe9s, Portugu\xe9s"},{specialty:"Especialista en Estilo & Brushing",bio:"Lea aporta un toque refinado a cada estilo — desde brushings de precisi\xf3n hasta looks pulidos para el d\xeda a d\xeda. Su dedicaci\xf3n a hacer que cada cliente se sienta hermosa y segura se refleja en cada servicio que realiza.",languages:"Ingl\xe9s"},{specialty:"Estilista Creativa",bio:"El ojo creativo y la precisi\xf3n t\xe9cnica de Tabby la convierten en una de las estilistas m\xe1s vers\xe1tiles de Blend. Ya sea que busques una transformaci\xf3n completa o una actualizaci\xf3n refinada de tu look, Tabby aporta visi\xf3n y creatividad a cada silla.",languages:"Ingl\xe9s"},{specialty:"Especialista en Corte y Estilo",bio:"Edith combina precisi\xf3n t\xe9cnica con un sentido intuitivo de lo que funciona para cada cliente individual. Su expertise en cortes y estilismo le ha valido una calificaci\xf3n perfecta y un c\xedrculo creciente de clientes dedicados.",languages:"Ingl\xe9s, Espa\xf1ol"},{specialty:"Artista en Color & Extensiones",bio:"Beatriz aporta creatividad y precisi\xf3n a los servicios de color y extensiones, ayudando a los clientes a lograr el largo, volumen y dimensi\xf3n que siempre so\xf1aron. Su enfoque meticuloso y calidez crean una experiencia verdaderamente personalizada.",languages:"Ingl\xe9s, Portugu\xe9s"},{specialty:"Especialista en Dise\xf1o de Cejas",bio:"Adriana es la artista de cejas de Blend, especializada en dise\xf1o y modelado que enmarca perfectamente cada rostro. Su precisi\xf3n y atenci\xf3n a la arquitectura facial crean cejas pulidas, naturales y exclusivamente adaptadas a cada cliente.",languages:"Ingl\xe9s, Portugu\xe9s"},{specialty:"Esteticista & Especialista en L\xe1ser",bio:"Esteticista licenciada y t\xe9cnica en l\xe1ser, Fran ayuda a los clientes a sentirse seguros a trav\xe9s de faciales personalizados y depilaci\xf3n l\xe1ser sin dolor. Su expertise cl\xednica y genuina pasi\xf3n por el bienestar de la piel crean resultados transformadores que van mucho m\xe1s all\xe1 de la belleza superficial.",languages:"Ingl\xe9s"}],pages:{services:{eyebrow:"Nuestro Arte",h1:"Servicios Exclusivos",sub:"Cada servicio en Blend es una experiencia cuidadosamente dise\xf1ada — desde la primera conversaci\xf3n hasta el resultado final.",faqEyebrow:"Preguntas Frecuentes",faqH2a:"Preguntas ",faqH2b:"Respondidas"},gallery:{eyebrow:"Nuestro Trabajo",h1a:"Galer\xeda de ",h1b:"Belleza"},team:{eyebrow:"Las Artistas",h1a:"Conoce al ",h1b:"Equipo de Belleza",sub:"Cada integrante del equipo Blend aporta experiencia, pasi\xf3n y un profundo compromiso con la belleza personalizada.",languages:"Idiomas",bookBtn:"Reservar Cita"},about:{eyebrow:"Nuestra Historia",h1a:"Belleza con ",h1b:"Alma Brasile\xf1a",sub:"Blend Hair Boutique naci\xf3 del amor por la belleza, el compromiso con el oficio y la tradici\xf3n brasile\xf1a de hospitalidad genuina y sin apuros.",storyEyebrow:"Qui\xe9nes Somos",storyH2a:"Un Boutique Construido en la ",storyH2b:"Conexi\xf3n",storyBody:["Blend Hair Boutique es un sal\xf3n y boutique de belleza completo en Plantation, Florida. Reunimos el calor brasile\xf1o y la t\xe9cnica de clase mundial bajo el mismo techo.","Nuestros servicios abarcan coloraci\xf3n, balayage, tratamientos alisadores, cortes y estilizado, u\xf1as, faciales, spa, depilaci\xf3n y belleza para novias y eventos — todo dise\xf1ado en torno al individuo.","Creemos que la belleza es personal. Cada visita comienza con una conversaci\xf3n, no con suposiciones. Nos tomamos el tiempo para entender tu cabello, tu estilo de vida y tu visi\xf3n — luego creamos algo que se siente inconfundiblemente como t\xfa."],storyBtn:"Reservar una Visita",valuesEyebrow:"Nuestros Valores",valuesH2a:"Lo que nos hace ",valuesH2b:"\xfanicos",values:[{title:"Hospitalidad Brasile\xf1a",body:"Calidez, cuidado y conexi\xf3n genuina est\xe1n en el coraz\xf3n de todo lo que hacemos. Cada clienta es bienvenida como una invitada en nuestro hogar."},{title:"Belleza Personalizada",body:"No hay dos clientas iguales. Cada servicio comienza con una consulta atenta para entender tu cabello, tu vida y tu visi\xf3n."},{title:"Excelencia Profesional",body:"Invertimos en formaci\xf3n, productos profesionales y t\xe9cnica refinada — porque tus resultados siempre deben hablar por s\xed mismos."}],communityEyebrow:"Nuestra Comunidad",communityH2a:"Con orgullo en ",communityH2b:"Plantation, Florida",communityBody:"Blend Hair Boutique es parte de la comunidad de Plantation — y nuestras clientas son nuestras vecinas, amigas, familia extendida. Nos honra ser parte de sus vidas y transformaciones.",communityBook:"Reservar Cita",communityCall:"Llamar",ctaEyebrow:"Ven a Vivir el Blend",ctaH2:"Tu Belleza, a Tu Manera.",ctaSub:"Transformaciones de belleza personalizadas dise\xf1adas para tu cabello, estilo de vida y confianza. En Plantation, Florida."},contact:{eyebrow:"Cont\xe1ctanos",h1a:"Nos Encantar\xeda ",h1b:"Saber de Ti",visitTitle:"Visita el Boutique",visitBody:"Estamos convenientemente ubicados en Plantation, Florida. Se aceptan clientas sin cita previa, pero se recomienda hacer una reserva.",formTitle:"Env\xeda un Mensaje",formBody:"\xbfPreguntas? \xbfPedidos especiales? Te responderemos pronto.",formSentTitle:"Gracias por contactarnos.",formSentBody:"Nos pondremos en contacto pronto. Mientras tanto, si\xe9ntete libre de reservar directamente en l\xednea.",fields:{name:"Tu Nombre",namePlaceholder:"\xbfC\xf3mo debemos llamarte?",email:"Correo Electr\xf3nico",emailPlaceholder:"Tu direcci\xf3n de correo",service:"Servicio de Inter\xe9s",serviceOptions:["Coloraci\xf3n & Balayage","Corte & Estilizado","Brushing Brasile\xf1o & Keratina","U\xf1as","Faciales & Spa","Novias & Eventos","Otro"],message:"Mensaje",messagePlaceholder:"Cu\xe9ntanos qu\xe9 est\xe1s buscando...",submit:"Enviar por WhatsApp"},ctaEyebrow:"\xbfLista para Empezar?",ctaH2:"Reserva Tu Cita Hoy.",ctaSub:"La forma m\xe1s f\xe1cil de vivir el Blend. Elige el servicio y el horario — nosotras nos encargamos del resto."}},mobileCta:{call:"Llamar",book:"Reservar",whatsapp:"WhatsApp"},mobileMenu:{bookBtn:"Reservar Cita"}}}}}]);